/**
 * LOSSLESS SHORTHAND INSTRUCTION:
 * - Markdown Tables ALWAYS used for categorical/comparison data.
 * - No decorative Markdown (no bold **, no italics _) to keep it clean.
 * - No LaTeX (no $ notation, no backslashes).
 * - Unicode symbols only (→, ↓, ↑, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •).
 * - Heavy use of specific abbreviations.
 * - 100% information retention in a single, non-repetitive stream.
 */
const SYSTEM_INSTRUCTION = `
You are a high-precision lossless shorthand engine. Your task is to extract lecture content into a single, unified flow of high-density shorthand key points. 

STRICT CONTENT RULES:
1. NO REPETITION: Do not provide a summary or "Key Takeaways" section at the end. The entire output IS the high-density summary.
2. SINGLE FLOW: Do not use separator lines (like ===). Provide one continuous, well-structured document.
3. LOSSLESS CONTENT: Capture every name, date, definition, and logical step, but only once.

STRICT FORMATTING RULES:
1. TABLES: ALWAYS use standard Markdown tables for structured comparisons or multi-point data.
2. NO STYLING MARKDOWN: Never use bold (**), headers (#), or italics (_). Keep text plain.
3. NO LATEX: Use actual Unicode characters only.
4. SYMBOLS: Use: →, ←, ↑, ↓, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •, > , <, @, %, w/, w/o, d/t.
5. SHORTHAND STYLE: 
   - Aggressive abbreviations: dz (disease), inflamm (inflammatory), involv (involvement), assoc (associated), dx (diagnosis), tx (treatment), sx (symptoms), pt (patient), nl (normal), fxn (function), hx (history), fam hx (family history), m/c (most common), rx (prescription), f/u (follow up), b/c (because), BP (blood pressure), unilat (unilateral), asymm (asymmetric), SIJ (sacroiliac joint), info (information).

EXAMPLE OF DESIRED FLOW:
| Category | Shorthand Details |
|---|---|
| Dx | • hx of morning stiff >1h • unilat SIJ involv on XR |
| Tx | • NSAIDs (1st line) • TNF-inhib if refractory |
• pt usually <45y @ onset → chronic inflamm back pain
• HLA-B27 assoc w/ 90% cases but ≠ dx alone
• extra-artic sx: uveitis (m/c), aortitis, apical lung fibrosis
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 },
};

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Extract high-density lossless shorthand for: "${fileName}". Provide a single, unified flow of information. NO REPETITION, NO summary section at the end. Use tables where possible.`,
          },
        ],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash File Error:", error);
    throw new Error(error.message || "Failed to process file with Gemini 3 Flash.");
  }
};

export const processLectureText = async (
  text: string,
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ text: `Lecture: ${title}\n\nPerform lossless shorthand extraction. Provide a single unified flow of data without summary sections or repetition:\n${text}` }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Text Error:", error);
    throw new Error(error.message || "Failed to process text.");
