• pt presents w/ chronic inflamm back pain → improves w/ exercise (not rest)
• extra-artic sx: uveitis (m/c), aortitis, apical lung fibrosis
• Tx: NSAIDs (1st line) → TNF-inhib if refractory
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 },
};

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Extract high-density lossless shorthand for: "${fileName}". 
            IMPORTANT: Provide exactly ONE flow of information. 
            Do NOT repeat information. 
            Do NOT add a "Key Takeaways" section at the end. 
            The output must be a single, non-repetitive shorthand stream.`,
          },
        ],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash File Error:", error);
    throw new Error(error.message || "Failed to process file with Gemini 3 Flash.");
  }
};

export const processLectureText = async (
  text: string,
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `Lecture: ${title}\n\nPerform single-pass lossless shorthand extraction. Do not repeat anything. No summary section:\n${text}` 
        }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Text Error:", error);
    throw new Error(error.message || "Failed to process text.");
  }
};

export const processLectureUrl = async (
  url: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `YouTube link: ${url}. Perform SINGLE-PASS LOSSLESS SHORTHAND extraction. Do not add a summary or takeaways section at the end. Provide exactly one flow of dense info.` 
        }],
      },
      config: {
        ...GENERATION_CONFIG,
        tools: [{ googleSearch: {} }],
      },
    });

    if (!response.text) throw new Error("No response generated.");

    let output = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (sources && sources.length > 0) {
      output += "\n\nSOURCES FOUND:\n";
      sources.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          output += `• ${chunk.web.title || 'Source'}: ${chunk.web.uri}\n`;
        }
      });
    }

    return output;
  } catch (error: any) {
    console.error("Gemini 3 Flash URL Error:", error);
    throw new Error(error.message || "Failed to process URL content.");
  }
};

export const combineLectureSources = async (
  sources: string[],
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const combinedInput = sources.map((s, i) => `SOURCE ${i + 1}:\n${s}`).join("\n\n---\n\n");
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `Lecture Title: ${title}

          TASK: MERGE multiple sources into ONE single-pass, comprehensive, lossless shorthand stream.

          STRICT RULES:
          1. DE-DUPLICATE: Include info once only.
          2. NO SUMMARY: The entire body is the notes. Do not add a summary or recap section.
          3. LOSSLESS: MISS NOTHING.
          4. STYLE: Extreme shorthand + Unicode symbols.

          SOURCES TO MERGE:
          ${combinedInput}` 
        }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Merge Error:", error);
    throw new Error(error.message || "Failed to merge sources.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { NoteEntry, ProcessingState } from './types';
import { processLectureFile, processLectureText, processLectureUrl, combineLectureSources } from './services/geminiService';
import HistorySidebar from './components/HistorySidebar';
import LoadingOverlay from './components/LoadingOverlay';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

type InputMode = 'media' | 'text' | 'youtube' | 'combine';

const App: React.FC = () => {
  const [history, setHistory] = useState<NoteEntry[]>([]);
  const [currentNote, setCurrentNote] = useState<NoteEntry | null>(null);
  const [inputMode, setInputMode] = useState<InputMode>('media');

  // Text state
  const [rawText, setRawText] = useState('');
  const [textTitle, setTextTitle] = useState('');

  // Youtube state
  const [ytLink, setYtLink] = useState('');

  // Combine state
  const [combineSources, setCombineSources] = useState<string[]>(['', '']);
  const [combineTitle, setCombineTitle] = useState('');

  const [processing, setProcessing] = useState<ProcessingState>({
    isProcessing: false,
    progress: '',
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('lecture_notes_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }

    // Add global paste listener for images
    const handleGlobalPaste = async (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      const imageBlobs: { blob: File, title: string }[] = [];
      const now = new Date().toLocaleTimeString();

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            imageBlobs.push({ 
              blob, 
              title: `Pasted Image ${imageBlobs.length + 1} (${now})` 
            });
          }
        }
      }

      // Process each image sequentially to ensure state updates correctly
      for (const item of imageBlobs) {
        await processFile(item.blob, item.title);
      }
    };

    window.addEventListener('paste', handleGlobalPaste);
    return () => window.removeEventListener('paste', handleGlobalPaste);
  }, []);

  useEffect(() => {
    localStorage.setItem('lecture_notes_history', JSON.stringify(history));
  }, [history]);

  const processFile = async (file: File, customTitle?: string) => {
    setProcessing({ isProcessing: true, progress: `Analyzing ${file.type.startsWith('image/') ? 'image' : 'source'} content...` });

    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result as string;
          const base64 = result.split(',')[1];
          resolve(base64);
        };
        reader.onerror = reject;
      });
      reader.readAsDataURL(file);

      const base64 = await base64Promise;
      setProcessing({ isProcessing: true, progress: 'Gemini 3 Flash is performing lossless shorthand extraction...' });

      const extractedContent = await processLectureFile(base64, file.type, file.name);

      const newNote: NoteEntry = {
        id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
        title: customTitle || file.name.split('.')[0] || 'Untitled Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: file.name,
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setProcessing({ isProcessing: false, progress: '' });
      setInputMode('media'); 
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    // Process multiple uploaded files
    const processBatch = async () => {
      for (let i = 0; i < files.length; i++) {
        await processFile(files[i]);
      }
    };
    processBatch();

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleTextShrink = async () => {
    if (!rawText.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Performing single-pass encoding...' });
    try {
      const title = textTitle.trim() || 'Pasted Text Lecture';
      const extractedContent = await processLectureText(rawText, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: 'Text Input',
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setRawText('');
      setTextTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleYoutubeShrink = async () => {
    if (!ytLink.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Locating lecture content and transcript...' });
    try {
      const extractedContent = await processLectureUrl(ytLink);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: 'YouTube Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: ytLink,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setYtLink('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleMergeShrink = async () => {
    const validSources = combineSources.filter(s => s.trim() !== '');
    if (validSources.length < 2) return;
    setProcessing({ isProcessing: true, progress: 'Combining sources without loss...' });
    try {
      const title = combineTitle.trim() || 'Comprehensive Combined Lecture';
      const extractedContent = await combineLectureSources(validSources, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: `Merged (${validSources.length} sources)`,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setCombineSources(['', '']);
      setCombineTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const updateCombineSource = (index: number, val: string) => {
    const next = [...combineSources];
    next[index] = val;
    setCombineSources(next);
  };

  const addCombineField = () => setCombineSources([...combineSources, '']);
  const removeCombineField = (index: number) => {
    if (combineSources.length <= 2) return;
    setCombineSources(combineSources.filter((_, i) => i !== index));
  };

  const copyToClipboard = async (text: string) => {
    if (!contentRef.current) {
      await navigator.clipboard.writeText(text);
      return;
    }

    try {
      const html = contentRef.current.innerHTML;
      const blobHtml = new Blob([html], { type: 'text/html' });
      const blobText = new Blob([text], { type: 'text/plain' });

      const data = [new ClipboardItem({
        'text/html': blobHtml,
        'text/plain': blobText,
      })];

      await navigator.clipboard.write(data);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy rich text: ', err);
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const deleteNote = (id: string) => {
    setHistory(prev => prev.filter(n => n.id !== id));
    if (currentNote?.id === id) setCurrentNote(null);
  };

  const renderContent = (content: string) => {
    const html = marked.parse(content, { breaks: true, gfm: true }) as string;
    const cleanHtml = DOMPurify.sanitize(html);
    return { __html: cleanHtml };
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <HistorySidebar 
        history={history} 
        onSelect={setCurrentNote} 
        onDelete={deleteNote}
        currentId={currentNote?.id}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 p-4 md:p-8 flex flex-col max-w-5xl mx-auto w-full">
        <header className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2">
              <i className="fa-solid fa-bolt-lightning text-yellow-500"></i>
              Note Shrinker
            </h1>
            <p className="text-slate-500 mt-1">Lossless extraction. High-density de-duplication.</p>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="md:hidden p-2 text-slate-600 hover:text-slate-900"
          >
            <i className="fa-solid fa-bars text-xl"></i>
          </button>
        </header>

        {/* Input Switcher */}
        <div className="flex bg-slate-200 p-1 rounded-xl w-fit mb-6 self-center shadow-inner overflow-x-auto max-w-full">
          {[
            { id: 'media', icon: 'fa-microphone-lines', label: 'Media / Image' },
            { id: 'text', icon: 'fa-align-left', label: 'Text' },
            { id: 'youtube', icon: 'fa-youtube', label: 'YouTube', color: 'text-red-500' },
            { id: 'combine', icon: 'fa-layer-group', label: 'Combine Sources' }
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setInputMode(tab.id as InputMode)}
              className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${inputMode === tab.id ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <i className={`fa-solid ${tab.id === 'youtube' ? 'fa-brands' : 'fa-solid'} ${tab.icon} mr-2 ${tab.color || ''}`}></i>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Input Area */}
        <div className="mb-8">
          {inputMode === 'media' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 text-center hover:border-blue-300 transition-colors group cursor-pointer relative overflow-hidden"
              onClick={() => fileInputRef.current?.click()}>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="audio/*,video/*,image/*,application/pdf,text/plain" 
                className="hidden"
                multiple
              />
              <div className="flex flex-col items-center py-4">
                <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-file-arrow-up text-2xl"></i>
                </div>
                <h3 className="text-lg font-semibold text-slate-800">Media Extraction</h3>
                <p className="text-slate-500 text-sm mt-1">Upload Recordings, PDFs, or <span className="text-blue-600 font-bold">Paste (Ctrl+V) Multiple Images</span></p>
                <div className="mt-4 flex gap-2">
                   <span className="px-2 py-1 bg-slate-100 rounded text-[10px] text-slate-500 uppercase font-bold tracking-tighter">Audio</span>
                   <span className="px-2 py-1 bg-slate-100 rounded text-[10px] text-slate-500 uppercase font-bold tracking-tighter">Video</span>
                   <span className="px-2 py-1 bg-slate-100 rounded text-[10px] text-slate-500 uppercase font-bold tracking-tighter">Images</span>
                   <span className="px-2 py-1 bg-slate-100 rounded text-[10px] text-slate-500 uppercase font-bold tracking-tighter">PDF</span>
                </div>
              </div>
              <div className="absolute inset-0 bg-blue-500/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </section>
          )}

          {inputMode === 'text' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <input 
                type="text"
                placeholder="Lecture Title (optional)"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm font-medium"
                value={textTitle}
                onChange={(e) => setTextTitle(e.target.value)}
              />
              <textarea 
                className="w-full min-h-[160px] p-4 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm resize-none"
                placeholder="Paste the content here for lossless shorthand conversion..."
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
              ></textarea>
              <button 
                onClick={handleTextShrink}
                disabled={!rawText.trim()}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <i className="fa-solid fa-wand-magic-sparkles"></i>
                Extract Lossless Notes
              </button>
            </section>
          )}

          {inputMode === 'youtube' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <div className="flex flex-col gap-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider px-1">YouTube Lecture Link</label>
                <div className="relative">
                  <i className="fa-brands fa-youtube absolute left-4 top-1/2 -translate-y-1/2 text-red-500"></i>
                  <input 
                    type="url"
                    placeholder="https://www.youtube.com/watch?v=..."
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-red-500/10 text-sm"
                    value={ytLink}
                    onChange={(e) => setYtLink(e.target.value)}
                  />
                </div>
              </div>
              <button 
                onClick={handleYoutubeShrink}
                disabled={!ytLink.trim()}
                className="bg-slate-900 hover:bg-black disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-slate-900/10"
              >
                <i className="fa-solid fa-magnifying-glass"></i>
                Fetch & Extract
              </button>
            </section>
          )}

          {inputMode === 'combine' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-6">
              <div className="flex flex-col gap-4">
                <div className="flex items-center gap-3 border-b border-slate-100 pb-4">
                  <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center">
                    <i className="fa-solid fa-object-group"></i>
                  </div>
                  <div className="flex-1">
                    <h3 className="font-bold text-slate-800">Combine Multiple Sources</h3>
                    <p className="text-xs text-slate-500">Merge different recordings/notes into one lossless version.</p>
                  </div>
                </div>
                <input 
                  type="text"
                  placeholder="Lecture Title (e.g. Clinical Medicine - SpAs)"
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm font-bold"
                  value={combineTitle}
                  onChange={(e) => setCombineTitle(e.target.value)}
                />
                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar p-1">
                  {combineSources.map((source, idx) => (
                    <div key={idx} className="relative group animate-in fade-in slide-in-from-right-4 duration-300">
                      <div className="absolute -left-2 top-3 w-6 h-6 bg-slate-100 border border-slate-200 text-slate-400 rounded-full flex items-center justify-center text-[10px] font-bold z-10">
                        {idx + 1}
                      </div>
                      <textarea 
                        className="w-full min-h-[120px] p-4 pl-6 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm resize-none bg-slate-50/30 transition-shadow"
                        placeholder={`Paste source ${idx + 1} content here (transcript, old notes, etc.)`}
                        value={source}
                        onChange={(e) => updateCombineSource(idx, e.target.value)}
                      ></textarea>
                      {combineSources.length > 2 && (
                        <button 
                          onClick={() => removeCombineField(idx)}
                          className="absolute right-3 top-3 text-slate-300 hover:text-red-500 transition-colors"
                          title="Remove source"
                        >
                          <i className="fa-solid fa-circle-xmark"></i>
                        </button>
                      )}
                    </div>
                  ))}
                </div>
                <button 
                  onClick={addCombineField}
                  className="w-full py-3 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 hover:text-indigo-500 hover:border-indigo-200 transition-all text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-2"
                >
                  <i className="fa-solid fa-plus-circle text-base"></i>
                  Add Another Source
                </button>
              </div>
              <button 
                onClick={handleMergeShrink}
                disabled={combineSources.filter(s => s.trim() !== '').length < 2}
                className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 px-6 rounded-xl flex items-center justify-center gap-3 transition-all shadow-xl shadow-indigo-600/20 group"
              >
                <i className="fa-solid fa-code-merge group-hover:rotate-12 transition-transform"></i>
                Create Comprehensive Shorthand
              </button>
              <div className="flex items-center justify-center gap-4 text-[10px] text-slate-400">
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> No info loss</span>
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> De-duplicated</span>
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> Medical Shorthand</span>
              </div>
            </section>
          )}
        </div>

        {/* Notes Display */}
        {currentNote ? (
          <div className="flex-1 flex flex-col bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
              <div className="min-w-0 flex-1 pr-4">
                <h2 className="font-bold text-slate-800 flex items-center gap-2 truncate">
                  <i className="fa-solid fa-file-lines text-blue-500"></i>
                  {currentNote.title}
                </h2>
                <span className="text-[10px] text-slate-400 font-mono block truncate">
                  {new Date(currentNote.timestamp).toLocaleString()} • {currentNote.fileName}
                </span>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => copyToClipboard(currentNote.content)}
                  className={`p-2 rounded-lg transition-all ${copySuccess ? 'bg-green-100 text-green-600' : 'hover:bg-slate-200 text-slate-600'}`}
                  title={copySuccess ? "Copied Rich Text!" : "Copy to clipboard (Rich Text)"}
                >
                  {copySuccess ? <i className="fa-solid fa-check"></i> : <i className="fa-regular fa-copy"></i>}
                </button>
              </div>
            </div>
            <div className="p-6 overflow-y-auto flex-1 bg-white scrollbar-thin">
              <div 
                ref={contentRef}
                className="markdown-content mono text-[13px] leading-relaxed text-slate-800 overflow-x-auto"
                dangerouslySetInnerHTML={renderContent(currentNote.content)}
              />
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl py-12">
            <i className="fa-solid fa-paste text-4xl mb-4 opacity-20"></i>
            <p className="text-sm">Processed notes will appear here.</p>
            <p className="text-[10px] mt-2 opacity-60">Tip: Paste multiple images (Ctrl+V) directly anywhere!</p>
          </div>
        )}

        {processing.error && (
          <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 text-sm flex items-center gap-3 animate-in shake duration-500">
            <i className="fa-solid fa-circle-exclamation"></i>
            <span className="flex-1">{processing.error}</span>
            <button 
              onClick={() => setProcessing({ ...processing, error: undefined })}
              className="p-1 hover:bg-red-100 rounded"
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        )}
      </main>

      <LoadingOverlay active={processing.isProcessing} message={processing.progress} />
      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .shake {
          animation: shake 0.5s ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { NoteEntry, ProcessingState } from './types';
import { processLectureFile, processLectureText, processLectureUrl, combineLectureSources } from './services/geminiService';
import HistorySidebar from './components/HistorySidebar';
import LoadingOverlay from './components/LoadingOverlay';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

type InputMode = 'media' | 'text' | 'youtube' | 'combine';

interface StagedFile {
  id: string;
  file: File;
  preview: string;
}

const App: React.FC = () => {
  const [history, setHistory] = useState<NoteEntry[]>([]);
  const [currentNote, setCurrentNote] = useState<NoteEntry | null>(null);
  const [inputMode, setInputMode] = useState<InputMode>('media');
  const [stagedFiles, setStagedFiles] = useState<StagedFile[]>([]);

  // Text state
  const [rawText, setRawText] = useState('');
  const [textTitle, setTextTitle] = useState('');

  // Youtube state
  const [ytLink, setYtLink] = useState('');

  // Combine state
  const [combineSources, setCombineSources] = useState<string[]>(['', '']);
  const [combineTitle, setCombineTitle] = useState('');

  const [processing, setProcessing] = useState<ProcessingState>({
    isProcessing: false,
    progress: '',
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('lecture_notes_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }

    // Global paste listener: Adds to stage instead of processing
    const handleGlobalPaste = async (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      const newStaged: StagedFile[] = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const id = Math.random().toString(36).substr(2, 9);
            const preview = URL.createObjectURL(blob);
            newStaged.push({ id, file: blob, preview });
          }
        }
      }

      if (newStaged.length > 0) {
        setStagedFiles(prev => [...prev, ...newStaged]);
        setInputMode('media');
      }
    };

    window.addEventListener('paste', handleGlobalPaste);
    return () => window.removeEventListener('paste', handleGlobalPaste);
  }, []);

  useEffect(() => {
    localStorage.setItem('lecture_notes_history', JSON.stringify(history));
  }, [history]);

  const processSingleFile = async (file: File, customTitle?: string) => {
    setProcessing({ isProcessing: true, progress: `Analyzing ${file.name}...` });

    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result as string;
          const base64 = result.split(',')[1];
          resolve(base64);
        };
        reader.onerror = reject;
      });
      reader.readAsDataURL(file);

      const base64 = await base64Promise;
      setProcessing({ isProcessing: true, progress: `Gemini 3 Flash: Extracting high-density shorthand from ${file.name}...` });

      const extractedContent = await processLectureFile(base64, file.type, file.name);

      const newNote: NoteEntry = {
        id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
        title: customTitle || file.name.split('.')[0] || 'Untitled Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: file.name,
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
    } catch (err: any) {
      setProcessing(prev => ({ ...prev, error: err.message }));
      throw err;
    }
  };

  const handleProcessStaged = async () => {
    if (stagedFiles.length === 0) return;

    setProcessing({ isProcessing: true, progress: 'Initializing batch extraction...' });

    try {
      for (const staged of stagedFiles) {
        await processSingleFile(staged.file);
      }
      // Clear stage after success
      stagedFiles.forEach(s => URL.revokeObjectURL(s.preview));
      setStagedFiles([]);
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newStaged: StagedFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const id = Math.random().toString(36).substr(2, 9);
      const preview = file.type.startsWith('image/') ? URL.createObjectURL(file) : '';
      newStaged.push({ id, file, preview });
    }
    setStagedFiles(prev => [...prev, ...newStaged]);

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeStaged = (id: string) => {
    setStagedFiles(prev => {
      const item = prev.find(s => s.id === id);
      if (item?.preview) URL.revokeObjectURL(item.preview);
      return prev.filter(s => s.id !== id);
    });
  };

  const handleTextShrink = async () => {
    if (!rawText.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Performing single-pass encoding...' });
    try {
      const title = textTitle.trim() || 'Pasted Text Lecture';
      const extractedContent = await processLectureText(rawText, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: 'Text Input',
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setRawText('');
      setTextTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleYoutubeShrink = async () => {
    if (!ytLink.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Locating lecture content and transcript...' });
    try {
      const extractedContent = await processLectureUrl(ytLink);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: 'YouTube Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: ytLink,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setYtLink('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleMergeShrink = async () => {
    const validSources = combineSources.filter(s => s.trim() !== '');
    if (validSources.length < 2) return;
    setProcessing({ isProcessing: true, progress: 'Combining sources without loss...' });
    try {
      const title = combineTitle.trim() || 'Comprehensive Combined Lecture';
      const extractedContent = await combineLectureSources(validSources, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: `Merged (${validSources.length} sources)`,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setCombineSources(['', '']);
      setCombineTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const updateCombineSource = (index: number, val: string) => {
    const next = [...combineSources];
    next[index] = val;
    setCombineSources(next);
  };

  const addCombineField = () => setCombineSources([...combineSources, '']);
  const removeCombineField = (index: number) => {
    if (combineSources.length <= 2) return;
    setCombineSources(combineSources.filter((_, i) => i !== index));
  };

  const copyToClipboard = async (text: string) => {
    if (!contentRef.current) {
      await navigator.clipboard.writeText(text);
      return;
    }

    try {
      const html = contentRef.current.innerHTML;
      const blobHtml = new Blob([html], { type: 'text/html' });
      const blobText = new Blob([text], { type: 'text/plain' });

      const data = [new ClipboardItem({
        'text/html': blobHtml,
        'text/plain': blobText,
      })];

      await navigator.clipboard.write(data);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy rich text: ', err);
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const deleteNote = (id: string) => {
    setHistory(prev => prev.filter(n => n.id !== id));
    if (currentNote?.id === id) setCurrentNote(null);
  };

  const renderContent = (content: string) => {
    const html = marked.parse(content, { breaks: true, gfm: true }) as string;
    const cleanHtml = DOMPurify.sanitize(html);
    return { __html: cleanHtml };
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <HistorySidebar 
        history={history} 
        onSelect={setCurrentNote} 
        onDelete={deleteNote}
        currentId={currentNote?.id}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 p-4 md:p-8 flex flex-col max-w-5xl mx-auto w-full">
        <header className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2">
              <i className="fa-solid fa-bolt-lightning text-yellow-500"></i>
              Note Shrinker
            </h1>
            <p className="text-slate-500 mt-1">Lossless extraction. High-density de-duplication.</p>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="md:hidden p-2 text-slate-600 hover:text-slate-900"
          >
            <i className="fa-solid fa-bars text-xl"></i>
          </button>
        </header>

        {/* Input Switcher */}
        <div className="flex bg-slate-200 p-1 rounded-xl w-fit mb-6 self-center shadow-inner overflow-x-auto max-w-full">
          {[
            { id: 'media', icon: 'fa-microphone-lines', label: 'Media / Image' },
            { id: 'text', icon: 'fa-align-left', label: 'Text' },
            { id: 'youtube', icon: 'fa-youtube', label: 'YouTube', color: 'text-red-500' },
            { id: 'combine', icon: 'fa-layer-group', label: 'Combine Sources' }
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setInputMode(tab.id as InputMode)}
              className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${inputMode === tab.id ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <i className={`fa-solid ${tab.id === 'youtube' ? 'fa-brands' : 'fa-solid'} ${tab.icon} mr-2 ${tab.color || ''}`}></i>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Input Area */}
        <div className="mb-8">
          {inputMode === 'media' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-6">
              {stagedFiles.length === 0 ? (
                <div 
                  className="p-12 text-center border-2 border-dashed border-slate-200 rounded-2xl hover:border-blue-300 transition-colors group cursor-pointer"
                  onClick={() => fileInputRef.current?.click()}
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    accept="audio/*,video/*,image/*,application/pdf,text/plain" 
                    className="hidden"
                    multiple
                  />
                  <div className="flex flex-col items-center">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                      <i className="fa-solid fa-file-arrow-up text-2xl"></i>
                    </div>
                    <h3 className="text-lg font-semibold text-slate-800">Media Queue</h3>
                    <p className="text-slate-500 text-sm mt-1">Upload files or <span className="text-blue-600 font-bold">Paste (Ctrl+V) images</span> repeatedly.</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="flex justify-between items-center px-1">
                    <h3 className="font-bold text-slate-800 text-sm uppercase tracking-wider">
                      Staged Files ({stagedFiles.length})
                    </h3>
                    <button 
                      onClick={() => setStagedFiles([])}
                      className="text-xs font-bold text-red-500 hover:text-red-600 flex items-center gap-1"
                    >
                      <i className="fa-solid fa-trash-can"></i> Clear All
                    </button>
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 max-h-[300px] overflow-y-auto p-1 custom-scrollbar">
                    {stagedFiles.map((staged) => (
                      <div key={staged.id} className="relative group aspect-video bg-slate-100 rounded-xl overflow-hidden border border-slate-200 animate-in zoom-in-95 duration-200">
                        {staged.preview ? (
                          <img src={staged.preview} alt="staged" className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-slate-400">
                            <i className="fa-solid fa-file-lines text-2xl"></i>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <button 
                            onClick={() => removeStaged(staged.id)}
                            className="bg-red-500 text-white w-8 h-8 rounded-full hover:bg-red-600 transition-colors shadow-lg"
                          >
                            <i className="fa-solid fa-xmark"></i>
                          </button>
                        </div>
                        <div className="absolute bottom-0 inset-x-0 bg-white/90 backdrop-blur-sm px-2 py-1">
                          <p className="text-[10px] font-bold truncate text-slate-700">{staged.file.name}</p>
                        </div>
                      </div>
                    ))}
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="aspect-video border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 hover:border-blue-200 transition-all"
                    >
                      <i className="fa-solid fa-plus mb-1"></i>
                      <span className="text-[10px] font-bold uppercase">Add More</span>
                    </button>
                  </div>

                  <button 
                    onClick={handleProcessStaged}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-3 transition-all shadow-xl shadow-blue-600/20 group"
                  >
                    <i className="fa-solid fa-bolt-lightning group-hover:animate-pulse"></i>
                    Shrink All Staged Files
                  </button>
                  <p className="text-center text-[10px] text-slate-400 font-medium">
                    Files will be processed sequentially into your history.
                  </p>
                </div>
              )}
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="audio/*,video/*,image/*,application/pdf,text/plain" 
                className="hidden"
                multiple
              />
            </section>
          )}

          {inputMode === 'text' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <input 
                type="text"
                placeholder="Lecture Title (optional)"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm font-medium"
                value={textTitle}
                onChange={(e) => setTextTitle(e.target.value)}
              />
              <textarea 
                className="w-full min-h-[160px] p-4 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm resize-none"
                placeholder="Paste the content here for lossless shorthand conversion..."
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
              ></textarea>
              <button 
                onClick={handleTextShrink}
                disabled={!rawText.trim()}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <i className="fa-solid fa-wand-magic-sparkles"></i>
                Extract Lossless Notes
              </button>
            </section>
          )}

          {inputMode === 'youtube' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <div className="flex flex-col gap-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider px-1">YouTube Lecture Link</label>
                <div className="relative">
                  <i className="fa-brands fa-youtube absolute left-4 top-1/2 -translate-y-1/2 text-red-500"></i>
                  <input 
                    type="url"
                    placeholder="https://www.youtube.com/watch?v=..."
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-red-500/10 text-sm"
                    value={ytLink}
                    onChange={(e) => setYtLink(e.target.value)}
                  />
                </div>
              </div>
              <button 
                onClick={handleYoutubeShrink}
                disabled={!ytLink.trim()}
                className="bg-slate-900 hover:bg-black disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-slate-900/10"
              >
                <i className="fa-solid fa-magnifying-glass"></i>
                Fetch & Extract
              </button>
            </section>
          )}

          {inputMode === 'combine' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-6">
              <div className="flex flex-col gap-4">
                <div className="flex items-center gap-3 border-b border-slate-100 pb-4">
                  <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center">
                    <i className="fa-solid fa-object-group"></i>
                  </div>
                  <div className="flex-1">
                    <h3 className="font-bold text-slate-800">Combine Multiple Sources</h3>
                    <p className="text-xs text-slate-500">Merge different recordings/notes into one lossless version.</p>
                  </div>
                </div>
                <input 
                  type="text"
                  placeholder="Lecture Title (e.g. Clinical Medicine - SpAs)"
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm font-bold"
                  value={combineTitle}
                  onChange={(e) => setCombineTitle(e.target.value)}
                />
                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar p-1">
                  {combineSources.map((source, idx) => (
                    <div key={idx} className="relative group animate-in fade-in slide-in-from-right-4 duration-300">
                      <div className="absolute -left-2 top-3 w-6 h-6 bg-slate-100 border border-slate-200 text-slate-400 rounded-full flex items-center justify-center text-[10px] font-bold z-10">
                        {idx + 1}
                      </div>
                      <textarea 
                        className="w-full min-h-[120px] p-4 pl-6 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 text-sm resize-none bg-slate-50/30 transition-shadow"
                        placeholder={`Paste source ${idx + 1} content here (transcript, old notes, etc.)`}
                        value={source}
                        onChange={(e) => updateCombineSource(idx, e.target.value)}
                      ></textarea>
                      {combineSources.length > 2 && (
                        <button 
                          onClick={() => removeCombineField(idx)}
                          className="absolute right-3 top-3 text-slate-300 hover:text-red-500 transition-colors"
                          title="Remove source"
                        >
                          <i className="fa-solid fa-circle-xmark"></i>
                        </button>
                      )}
                    </div>
                  ))}
                </div>
                <button 
                  onClick={addCombineField}
                  className="w-full py-3 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 hover:text-indigo-500 hover:border-indigo-200 transition-all text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-2"
                >
                  <i className="fa-solid fa-plus-circle text-base"></i>
                  Add Another Source
                </button>
              </div>
              <button 
                onClick={handleMergeShrink}
                disabled={combineSources.filter(s => s.trim() !== '').length < 2}
                className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-4 px-6 rounded-xl flex items-center justify-center gap-3 transition-all shadow-xl shadow-indigo-600/20 group"
              >
                <i className="fa-solid fa-code-merge group-hover:rotate-12 transition-transform"></i>
                Create Comprehensive Shorthand
              </button>
              <div className="flex items-center justify-center gap-4 text-[10px] text-slate-400">
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> No info loss</span>
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> De-duplicated</span>
                <span className="flex items-center gap-1"><i className="fa-solid fa-check text-green-500"></i> Medical Shorthand</span>
              </div>
            </section>
          )}
        </div>

        {/* Notes Display */}
        {currentNote ? (
          <div className="flex-1 flex flex-col bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
              <div className="min-w-0 flex-1 pr-4">
                <h2 className="font-bold text-slate-800 flex items-center gap-2 truncate">
                  <i className="fa-solid fa-file-lines text-blue-500"></i>
                  {currentNote.title}
                </h2>
                <span className="text-[10px] text-slate-400 font-mono block truncate">
                  {new Date(currentNote.timestamp).toLocaleString()} • {currentNote.fileName}
                </span>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => copyToClipboard(currentNote.content)}
                  className={`p-2 rounded-lg transition-all ${copySuccess ? 'bg-green-100 text-green-600' : 'hover:bg-slate-200 text-slate-600'}`}
                  title={copySuccess ? "Copied Rich Text!" : "Copy to clipboard (Rich Text)"}
                >
                  {copySuccess ? <i className="fa-solid fa-check"></i> : <i className="fa-regular fa-copy"></i>}
                </button>
              </div>
            </div>
            <div className="p-6 overflow-y-auto flex-1 bg-white scrollbar-thin">
              <div 
                ref={contentRef}
                className="markdown-content mono text-[13px] leading-relaxed text-slate-800 overflow-x-auto"
                dangerouslySetInnerHTML={renderContent(currentNote.content)}
              />
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl py-12">
            <i className="fa-solid fa-paste text-4xl mb-4 opacity-20"></i>
            <p className="text-sm">Processed notes will appear here.</p>
            <p className="text-[10px] mt-2 opacity-60">Tip: Paste multiple images (Ctrl+V) directly anywhere to queue them!</p>
          </div>
        )}

        {processing.error && (
          <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 text-sm flex items-center gap-3 animate-in shake duration-500">
            <i className="fa-solid fa-circle-exclamation"></i>
            <span className="flex-1">{processing.error}</span>
            <button 
              onClick={() => setProcessing({ ...processing, error: undefined })}
              className="p-1 hover:bg-red-100 rounded"
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        )}
      </main>

      <LoadingOverlay active={processing.isProcessing} message={processing.progress} />
      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .shake {
          animation: shake 0.5s ease-in-out;
        }
      `}</style>
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

/**
 * LOSSLESS SHORTHAND INSTRUCTION:
 * - Single-pass extraction only.
 * - No Body + Summary structure.
 * - Markdown Tables used for categorical/comparison data.
 * - No decorative Markdown (no bold **, no italics _) to keep it clean.
 * - Unicode symbols only (→, ↓, ↑, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •).
 * - Heavy use of specific abbreviations.
 */
const SYSTEM_INSTRUCTION = `
You are a high-precision, single-pass shorthand engine. Your goal is to extract every piece of information from a lecture into exactly ONE unified, high-density stream.

STRICT CONTENT RULES:
1. NO REPETITION: Do not provide a body followed by a summary. Do not provide a "Key Takeaways" section at the end.
2. ONE FLOW: Start extracting immediately and stop when finished. The entire output IS the shorthand notes.
3. ZERO RECAP: Never use phrases like "In summary," "To conclude," or "Overall."
4. LOSSLESS: Capture every technical term, name, date, and logical connection, but only mention them ONCE.

STRICT FORMATTING RULES:
1. TABLES: Use Markdown tables for data that is naturally categorical or comparative.
2. BULLETS: Use high-density bullets for logical sequences.
3. NO STYLING: Do not use bold (**), headers (#), or italics (_). Use plain text structure.
4. UNICODE SYMBOLS: Use: →, ←, ↑, ↓, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •, > , <, @, %, w/, w/o, d/t.
5. MEDICAL/TECHNICAL SHORTHAND: 
   - dz (disease), inflamm (inflammatory), involv (involvement), assoc (associated), dx (diagnosis), tx (treatment), sx (symptoms), pt (patient), nl (normal), fxn (function), hx (history), fam hx (family history), m/c (most common), rx (prescription), f/u (follow up), b/c (because), BP (blood pressure), unilat (unilateral), asymm (asymmetric), SIJ (sacroiliac joint), info (information).

EXAMPLE OF DESIRED SINGLE-FLOW OUTPUT:
| Concept | Shorthand Details |
|---|---|
| Dx Criteria | • hx of morning stiff >1h • unilat SIJ involv on XR |
| Epidemiology | • m/c in males <45y @ onset • HLA-B27 assoc (90% cases) |
• pt presents w/ chronic inflamm back pain → improves w/ exercise (not rest)
• extra-artic sx: uveitis (m/c), aortitis, apical lung fibrosis
• Tx: NSAIDs (1st line) → TNF-inhib if refractory
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 },
};

export interface FilePart {
  base64: string;
  mimeType: string;
  fileName: string;
}

export const processBatchLectureFiles = async (
  files: FilePart[],
  sessionTitle: string
): Promise<string> => {
  const ai = getAI();
  try {
    const parts: any[] = files.map(f => ({
      inlineData: {
        data: f.base64,
        mimeType: f.mimeType
      }
    }));

    parts.push({
      text: `Extract high-density lossless shorthand for this session: "${sessionTitle}". 
      You are provided with ${files.length} images/documents. 
      IMPORTANT: Merge all information into exactly ONE unified flow. 
      Do NOT repeat information from different images. 
      Do NOT add a "Key Takeaways" section at the end. 
      The output must be a single, non-repetitive shorthand stream covering ALL provided materials.`
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: { parts },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Batch Error:", error);
    throw new Error(error.message || "Failed to process batch with Gemini 3 Flash.");
  }
};

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Extract high-density lossless shorthand for: "${fileName}". 
            IMPORTANT: Provide exactly ONE flow of information. 
            Do NOT repeat information. 
            Do NOT add a "Key Takeaways" section at the end. 
            The output must be a single, non-repetitive shorthand stream.`,
          },
        ],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash File Error:", error);
    throw new Error(error.message || "Failed to process file with Gemini 3 Flash.");
  }
};

export const processLectureText = async (
  text: string,
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `Lecture: ${title}\n\nPerform single-pass lossless shorthand extraction. Do not repeat anything. No summary section:\n${text}` 
        }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Text Error:", error);
    throw new Error(error.message || "Failed to process text.");
  }
};

export const processLectureUrl = async (
  url: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `YouTube link: ${url}. Perform SINGLE-PASS LOSSLESS SHORTHAND extraction. Do not add a summary or takeaways section at the end. Provide exactly one flow of dense info.` 
        }],
      },
      config: {
        ...GENERATION_CONFIG,
        tools: [{ googleSearch: {} }],
      },
    });

    if (!response.text) throw new Error("No response generated.");

    let output = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (sources && sources.length > 0) {
      output += "\n\nSOURCES FOUND:\n";
      sources.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          output += `• ${chunk.web.title || 'Source'}: ${chunk.web.uri}\n`;
        }
      });
    }

    return output;
  } catch (error: any) {
    console.error("Gemini 3 Flash URL Error:", error);
    throw new Error(error.message || "Failed to process URL content.");
  }
};

export const combineLectureSources = async (
  sources: string[],
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const combinedInput = sources.map((s, i) => `SOURCE ${i + 1}:\n${s}`).join("\n\n---\n\n");
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `Lecture Title: ${title}

          TASK: MERGE multiple sources into ONE single-pass, comprehensive, lossless shorthand stream.

          STRICT RULES:
          1. DE-DUPLICATE: Include info once only.
          2. NO SUMMARY: The entire body is the notes. Do not add a summary or recap section.
          3. LOSSLESS: MISS NOTHING.
          4. STYLE: Extreme shorthand + Unicode symbols.

          SOURCES TO MERGE:
          ${combinedInput}` 
        }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Merge Error:", error);
    throw new Error(error.message || "Failed to merge sources.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { NoteEntry, ProcessingState } from './types';
import { processLectureFile, processLectureText, processLectureUrl, combineLectureSources, processBatchLectureFiles, FilePart } from './services/geminiService';
import HistorySidebar from './components/HistorySidebar';
import LoadingOverlay from './components/LoadingOverlay';
import { marked } from 'marked';
import DOMPurify from 'dompurify';

type InputMode = 'media' | 'text' | 'youtube' | 'combine';

interface StagedFile {
  id: string;
  file: File;
  preview: string;
}

const App: React.FC = () => {
  const [history, setHistory] = useState<NoteEntry[]>([]);
  const [currentNote, setCurrentNote] = useState<NoteEntry | null>(null);
  const [inputMode, setInputMode] = useState<InputMode>('media');
  const [stagedFiles, setStagedFiles] = useState<StagedFile[]>([]);
  const [sessionTitle, setSessionTitle] = useState('');

  // Text state
  const [rawText, setRawText] = useState('');
  const [textTitle, setTextTitle] = useState('');

  // Youtube state
  const [ytLink, setYtLink] = useState('');

  // Combine state
  const [combineSources, setCombineSources] = useState<string[]>(['', '']);
  const [combineTitle, setCombineTitle] = useState('');

  const [processing, setProcessing] = useState<ProcessingState>({
    isProcessing: false,
    progress: '',
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('lecture_notes_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }

    const handleGlobalPaste = async (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      const newStaged: StagedFile[] = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const id = Math.random().toString(36).substr(2, 9);
            const preview = URL.createObjectURL(blob);
            newStaged.push({ id, file: blob, preview });
          }
        }
      }

      if (newStaged.length > 0) {
        setStagedFiles(prev => [...prev, ...newStaged]);
        setInputMode('media');
      }
    };

    window.addEventListener('paste', handleGlobalPaste);
    return () => window.removeEventListener('paste', handleGlobalPaste);
  }, []);

  useEffect(() => {
    localStorage.setItem('lecture_notes_history', JSON.stringify(history));
  }, [history]);

  const handleProcessStaged = async () => {
    if (stagedFiles.length === 0) return;

    setProcessing({ isProcessing: true, progress: `Processing ${stagedFiles.length} files as a single session...` });

    try {
      const fileParts: FilePart[] = [];

      for (const staged of stagedFiles) {
        const reader = new FileReader();
        const base64Promise = new Promise<string>((resolve, reject) => {
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
          reader.onerror = reject;
        });
        reader.readAsDataURL(staged.file);
        const base64 = await base64Promise;

        fileParts.push({
          base64,
          mimeType: staged.file.type,
          fileName: staged.file.name
        });
      }

      const finalTitle = sessionTitle.trim() || `Session (${new Date().toLocaleTimeString()})`;
      const extractedContent = await processBatchLectureFiles(fileParts, finalTitle);

      const newNote: NoteEntry = {
        id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
        title: finalTitle,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: `${stagedFiles.length} mixed files`,
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);

      // Clear stage
      stagedFiles.forEach(s => URL.revokeObjectURL(s.preview));
      setStagedFiles([]);
      setSessionTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    const newStaged: StagedFile[] = [];
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const id = Math.random().toString(36).substr(2, 9);
      const preview = file.type.startsWith('image/') ? URL.createObjectURL(file) : '';
      newStaged.push({ id, file, preview });
    }
    setStagedFiles(prev => [...prev, ...newStaged]);

    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeStaged = (id: string) => {
    setStagedFiles(prev => {
      const item = prev.find(s => s.id === id);
      if (item?.preview) URL.revokeObjectURL(item.preview);
      return prev.filter(s => s.id !== id);
    });
  };

  const handleTextShrink = async () => {
    if (!rawText.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Performing single-pass encoding...' });
    try {
      const title = textTitle.trim() || 'Pasted Text Lecture';
      const extractedContent = await processLectureText(rawText, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: 'Text Input',
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setRawText('');
      setTextTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleYoutubeShrink = async () => {
    if (!ytLink.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Locating lecture content and transcript...' });
    try {
      const extractedContent = await processLectureUrl(ytLink);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: 'YouTube Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: ytLink,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setYtLink('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleMergeShrink = async () => {
    const validSources = combineSources.filter(s => s.trim() !== '');
    if (validSources.length < 2) return;
    setProcessing({ isProcessing: true, progress: 'Combining sources without loss...' });
    try {
      const title = combineTitle.trim() || 'Comprehensive Combined Lecture';
      const extractedContent = await combineLectureSources(validSources, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: `Merged (${validSources.length} sources)`,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setCombineSources(['', '']);
      setCombineTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const updateCombineSource = (index: number, val: string) => {
    const next = [...combineSources];
    next[index] = val;
    setCombineSources(next);
  };

  const addCombineField = () => setCombineSources([...combineSources, '']);
  const removeCombineField = (index: number) => {
    if (combineSources.length <= 2) return;
    setCombineSources(combineSources.filter((_, i) => i !== index));
  };

  const copyToClipboard = async (text: string) => {
    if (!contentRef.current) {
      await navigator.clipboard.writeText(text);
      return;
    }

    try {
      const html = contentRef.current.innerHTML;
      const blobHtml = new Blob([html], { type: 'text/html' });
      const blobText = new Blob([text], { type: 'text/plain' });

      const data = [new ClipboardItem({
        'text/html': blobHtml,
        'text/plain': blobText,
      })];

      await navigator.clipboard.write(data);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error('Failed to copy rich text: ', err);
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const deleteNote = (id: string) => {
    setHistory(prev => prev.filter(n => n.id !== id));
    if (currentNote?.id === id) setCurrentNote(null);
  };

  const renderContent = (content: string) => {
    const html = marked.parse(content, { breaks: true, gfm: true }) as string;
    const cleanHtml = DOMPurify.sanitize(html);
    return { __html: cleanHtml };
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <HistorySidebar 
        history={history} 
        onSelect={setCurrentNote} 
        onDelete={deleteNote}
        currentId={currentNote?.id}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 p-4 md:p-8 flex flex-col max-w-5xl mx-auto w-full">
        <header className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2">
              <i className="fa-solid fa-bolt-lightning text-yellow-500"></i>
              Note Shrinker
            </h1>
            <p className="text-slate-500 mt-1">Lossless extraction. High-density de-duplication.</p>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="md:hidden p-2 text-slate-600 hover:text-slate-900"
          >
            <i className="fa-solid fa-bars text-xl"></i>
          </button>
        </header>

        {/* Input Switcher */}
        <div className="flex bg-slate-200 p-1 rounded-xl w-fit mb-6 self-center shadow-inner overflow-x-auto max-w-full">
          {[
            { id: 'media', icon: 'fa-microphone-lines', label: 'Media / Image' },
            { id: 'text', icon: 'fa-align-left', label: 'Text' },
            { id: 'youtube', icon: 'fa-youtube', label: 'YouTube', color: 'text-red-500' },
            { id: 'combine', icon: 'fa-layer-group', label: 'Combine Sources' }
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setInputMode(tab.id as InputMode)}
              className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${inputMode === tab.id ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <i className={`fa-solid ${tab.id === 'youtube' ? 'fa-brands' : 'fa-solid'} ${tab.icon} mr-2 ${tab.color || ''}`}></i>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Input Area */}
        <div className="mb-8">
          {inputMode === 'media' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-6">
              {stagedFiles.length === 0 ? (
                <div 
                  className="p-12 text-center border-2 border-dashed border-slate-200 rounded-2xl hover:border-blue-300 transition-colors group cursor-pointer"
                  onClick={() => fileInputRef.current?.click()}
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    accept="audio/*,video/*,image/*,application/pdf,text/plain" 
                    className="hidden"
                    multiple
                  />
                  <div className="flex flex-col items-center">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                      <i className="fa-solid fa-file-arrow-up text-2xl"></i>
                    </div>
                    <h3 className="text-lg font-semibold text-slate-800">Media Queue</h3>
                    <p className="text-slate-500 text-sm mt-1">Upload files or <span className="text-blue-600 font-bold">Paste (Ctrl+V) images</span> repeatedly.</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="flex justify-between items-center px-1">
                    <h3 className="font-bold text-slate-800 text-sm uppercase tracking-wider">
                      Staged for Single Response ({stagedFiles.length})
                    </h3>
                    <button 
                      onClick={() => setStagedFiles([])}
                      className="text-xs font-bold text-red-500 hover:text-red-600 flex items-center gap-1"
                    >
                      <i className="fa-solid fa-trash-can"></i> Clear All
                    </button>
                  </div>

                  <input 
                    type="text"
                    placeholder="Session Title (e.g. Immunology Part 1)"
                    className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm font-bold bg-slate-50/50"
                    value={sessionTitle}
                    onChange={(e) => setSessionTitle(e.target.value)}
                  />

                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 max-h-[300px] overflow-y-auto p-1 custom-scrollbar">
                    {stagedFiles.map((staged) => (
                      <div key={staged.id} className="relative group aspect-video bg-slate-100 rounded-xl overflow-hidden border border-slate-200 animate-in zoom-in-95 duration-200">
                        {staged.preview ? (
                          <img src={staged.preview} alt="staged" className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-slate-400">
                            <i className="fa-solid fa-file-lines text-2xl"></i>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <button 
                            onClick={() => removeStaged(staged.id)}
                            className="bg-red-500 text-white w-8 h-8 rounded-full hover:bg-red-600 transition-colors shadow-lg"
                          >
                            <i className="fa-solid fa-xmark"></i>
                          </button>
                        </div>
                        <div className="absolute bottom-0 inset-x-0 bg-white/90 backdrop-blur-sm px-2 py-1">
                          <p className="text-[10px] font-bold truncate text-slate-700">{staged.file.name}</p>
                        </div>
                      </div>
                    ))}
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="aspect-video border-2 border-dashed border-slate-200 rounded-xl flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 hover:border-blue-200 transition-all"
                    >
                      <i className="fa-solid fa-plus mb-1"></i>
                      <span className="text-[10px] font-bold uppercase">Add More</span>
                    </button>
                  </div>

