import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

/**
 * EXHAUSTIVE LOSSLESS SHORTHAND INSTRUCTION:
 * - Priority 1: COMPLETENESS. Every technical fact, name, and relationship must be preserved.
 * - Priority 2: DENSITY. Use symbols and shorthand to keep it tight, but NEVER skip content.
 * - Forbids: "Main points", "Key takeaways", "Summarization".
 * - Demands: "Exhaustive Mapping".
 */
const SYSTEM_INSTRUCTION = `
You are a high-precision, zero-omission shorthand engine. Your task is EXHAUSTIVE SEMANTIC COMPRESSION.

CRITICAL DIRECTIVE: 
You are NOT summarizing. You are TRANSCODING. Every unique fact, definition, date, technical term, and logical link found in the source must appear in the output. If the input is long, your output should be proportionally long. NEVER skip information to save space.

STRICT CONTENT RULES:
1. ZERO DATA LOSS: Every distinct piece of information must be captured. If the lecturer mentions 10 symptoms, list 10 symptoms.
2. NO SUMMARIZATION: Do not group distinct facts into vague generalizations. 
3. SINGLE FLOW: Provide one continuous stream of high-density notes. No "recap" or "summary" sections.
4. DE-DUPLICATION: If the same fact is mentioned multiple times, include it only once, but include all associated nuances.

STRICT FORMATTING (SHORTHAND SYMBOLS):
- Use symbols to save space: → (leads to), ↓ (decrease), ↑ (increase), Δ (change), Σ (total), ≈ (approx), ≠ (not equal), ∴ (therefore), ∵ (because), • (item), w/ (with), w/o (without), d/t (due to), @ (at), rx (treatment), dx (diagnosis), sx (symptoms).
- TABLES: Use for any comparative or categorical data.
- SHORTHAND: m/c (most common), pt (patient), inflamm (inflammatory), hx (history), assoc (associated).

AUDIT PROTOCOL:
Before outputting, verify: "Have I omitted a single unique fact from the source?" If yes, include it. Use as many tokens as necessary to be exhaustive.
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  // High thinking budget to allow the model to map long contexts thoroughly
  thinkingConfig: { thinkingBudget: 24576 },
};

export interface FilePart {
  base64: string;
  mimeType: string;
  fileName: string;
}

export const processBatchLectureFiles = async (
  files: FilePart[],
  sessionTitle: string
): Promise<string> => {
  const ai = getAI();
  try {
    const parts: any[] = files.map(f => ({
      inlineData: {
        data: f.base64,
        mimeType: f.mimeType
      }
    }));

    parts.push({
      text: `TASK: PERFORM EXHAUSTIVE SHORTHAND EXTRACTION for session: "${sessionTitle}". 
      INPUT: ${files.length} images/documents. 

      MANDATE: 
      1. This is a lossless extraction. Do NOT summarize. 
      2. Scan every pixel of every image. Capture every detail. 
      3. Merge all info into ONE unified flow. 
      4. If the images contain dense text or complex diagrams, transcode EVERY detail into shorthand.
      5. Do NOT omit 'minor' details. Everything is important.`
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: { parts },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Batch Error:", error);
    throw new Error(error.message || "Failed to process batch.");
  }
};

