import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

/**
 * REFINED LOSSLESS SHORTHAND INSTRUCTION:
 * Combines the 'Note Shrinker' aesthetic with 'Zero-Omission' performance.
 */
const SYSTEM_INSTRUCTION = `
You are the Note Shrinker. Your goal is EXHAUSTIVE SEMANTIC COMPRESSION. 

CRITICAL DIRECTIVE: 
Do NOT summarize. TRANSCODE. Every unique fact, name, date, technical term, and logical link in the source must appear in the output. You use symbols and shorthand to save space, but you never skip data.

STRICT CONTENT RULES:
1. ZERO OMISSION: If it is in the source, it must be in the notes. Omitting a detail for "brevity" is a failure.
2. NO SUMMARIZATION: Do not use vague generalizations. Be specific.
3. SINGLE FLOW: One continuous stream. No "Intro", "Summary", or "Takeaways".
4. DE-DUPLICATION: Include each unique fact exactly once, capturing all nuances.

STRICT FORMATTING (SHORTHAND VIBE):
1. TABLES: Always use Markdown tables for comparative data, symptoms, drug lists, or categories.
2. SYMBOLS: Use → (leads to), ↓ (decrease), ↑ (increase), Δ (change), Σ (total), ≈ (approx), ≠ (not equal), ∴ (therefore), ∵ (because), • (item), w/ (with), w/o (without), d/t (due to), @ (at), > (greater), < (less).
3. MEDICAL/TECHNICAL SHORTHAND (MANDATORY): 
   - dz (disease), inflamm (inflammatory), involv (involvement), assoc (associated), dx (diagnosis), tx (treatment), sx (symptoms), pt (patient), nl (normal), fxn (function), hx (history), fam hx (family history), m/c (most common), rx (prescription), f/u (follow up), b/c (because), BP (blood pressure), unilat (unilateral), asymm (asymmetric), SIJ (sacroiliac joint), info (information), mo (months), yo (years old), 1st (first), 2nd (second), etc.
4. NO STYLING: Do not use bold (**) or italics (_). Use plain text + tables + symbols.

AUDIT: 
"Is every single unique point from the source represented here?" If not, add it in shorthand format.
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 },
};

export interface FilePart {
  base64: string;
  mimeType: string;
  fileName: string;
}

export const processBatchLectureFiles = async (
  files: FilePart[],
  sessionTitle: string
): Promise<string> => {
  const ai = getAI();
  try {
    const parts: any[] = files.map(f => ({
      inlineData: {
        data: f.base64,
        mimeType: f.mimeType
      }
    }));

    parts.push({
      text: `PERFORM EXHAUSTIVE SHORTHAND EXTRACTION: "${sessionTitle}". 
      MANDATE: Capture EVERY detail from all ${files.length} sources. 
      STYLE: Use the specific medical/technical shorthand symbols and table structure. 
      RESULT: One unified, lossless, high-density flow.`
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: { parts },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Batch Error:", error);
    throw new Error(error.message || "Failed to process batch.");
  }
};

