export const processLectureUrl = async (
  url: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `YouTube link: ${url}. Perform EXHAUSTIVE extraction. Map every point from the video into dense shorthand. Do not summarize.` 
        }],
      },
      config: {
        ...GENERATION_CONFIG,
        tools: [{ googleSearch: {} }],
      },
    });

    if (!response.text) throw new Error("No response generated.");

    let output = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (sources && sources.length > 0) {
      output += "\n\nSOURCES FOUND:\n";
      sources.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          output += `• ${chunk.web.title || 'Source'}: ${chunk.web.uri}\n`;
        }
      });
    }

    return output;
  } catch (error: any) {
    console.error("Gemini 3 Flash URL Error:", error);
    throw new Error(error.message || "Failed to process URL.");
  }
};

