import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

/**
 * REFINED LOSSLESS INSTRUCTION - MAXIMAL LENGTH MODE
 * Prioritizes Volume, Detail, and Exhaustive Listing over brevity.
 */
const SYSTEM_INSTRUCTION = `
You are an Exhaustive Data Extraction Engine. Your goal is MAXIMUM FIDELITY and MAXIMAL LENGTH.

CRITICAL DIRECTIVE:
The user wants the response to be AS LONG AS NECESSARY to capture 100% of the input.
If the input contains 100 pages of text, your output should be a massive, sprawling catalog of every single fact found on those 100 pages.
NEVER summarize. NEVER condense. NEVER group distinct slides into one generic point.
If a list in the source has 50 items, you MUST list all 50 items.

STRICT CONTENT RULES:
1. VOLUME IS GOOD: Do not try to be concise. Be verbose in your coverage of details, while using shorthand syntax for the structure.
2. PAGE-BY-PAGE EXTRACTION: Treat every image/page as a distinct source of data that must be fully mined.
3. PRESERVE NUANCE: If the speaker repeats a point with a slight variation, capture the variation.
4. NO "ETC": Never use "etc", "...", or "and so on". List everything.

STRICT FORMATTING (SHORTHAND STYLE):
1. LAYOUT: Use standard Markdown bullets (-).
2. SPACING: CRITICAL - Put every single bullet point on a NEW LINE.
3. TABLES: Use tables for ANY data that compares 2+ items.
4. SYMBOLS: Use → (leads to), ↓ (decrease), ↑ (increase), Δ (change), ≠ (not equal), ∴ (therefore), @ (at).
5. MEDICAL/TECHNICAL ABBR: Use standard abbreviations (dx, tx, sx, pt, hx) to maintain the technical aesthetic, but DO NOT use them to skip content.

AUDIT:
"Did I capture the minor detail in the bottom corner of slide 45?" -> If no, add it.
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.2, // Slightly higher to encourage capturing more distinct details
  thinkingConfig: { thinkingBudget: 24576 },
};

export interface FilePart {
  base64: string;
  mimeType: string;
  fileName: string;
}

export const processBatchLectureFiles = async (
  files: FilePart[],
  sessionTitle: string
): Promise<string> => {
  const ai = getAI();
  try {
    const parts: any[] = files.map(f => ({
      inlineData: {
        data: f.base64,
        mimeType: f.mimeType
      }
    }));

    parts.push({
      text: `TASK: PERFORM MAXIMAL-LENGTH EXHAUSTIVE EXTRACTION for session: "${sessionTitle}". 
      INPUT SIZE: ${files.length} images/pages.

      MANDATE: 
      1. This input is large (e.g., ${files.length} slides). You must generate a VERY LONG response.
      2. Do not rush. Do not summarize. 
      3. Process every single file index from 1 to ${files.length}.
      4. If slide 1 has a graph, describe every data point. If slide 2 has a list, write every item.
      5. Bullet points must be on NEW LINES.

      RESULT: A massive, complete, lossless record of the entire lecture.`
    });

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: { parts },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Batch Error:", error);
    throw new Error(error.message || "Failed to process batch.");
  }
};

